WITH inner_cte AS ( SELECT tso.OFFER_DEPT_NAME AS department_name, COUNT(DISTINCT lrm.LIBRARY_RESERVE_CATALOG_KEY) AS total_reserved_materials FROM TIP_SUBJECT_OFFERED tso JOIN TIP_DETAIL td ON tso.SUBJECT_ID = td.SUBJECT_ID JOIN LIBRARY_RESERVE_MATRL_DETAIL lrm ON td.SUBJECT_ID = lrm.SUBJECT_ID WHERE tso.OFFER_SCHOOL_NAME IN ('Engineering', 'Science') AND tso.IS_NO_COURSE_MATERIAL = 'N' GROUP BY tso.OFFER_DEPT_NAME HAVING COUNT(DISTINCT lrm.LIBRARY_RESERVE_CATALOG_KEY) > 20 ) SELECT ic.department_name, ic.total_reserved_materials, cs.SUBJECT_TITLE, cs.TERM_CODE, cs.OFFER_DEPT_NAME, cs.RESPONSIBLE_FACULTY_NAME, cs.DEPARTMENT_FULL_NAME, cs.SCHOOL_NAME, cs.max_enrolled_students, ROUND(ic.total_reserved_materials / NULLIF(cs.max_enrolled_students, 0), 2) AS reserved_materials_per_max_enrollment FROM inner_cte ic JOIN ( SELECT t0.SUBJECT_TITLE, t0.TERM_CODE, t0.OFFER_DEPT_NAME, t0.RESPONSIBLE_FACULTY_NAME, t1.DEPARTMENT_FULL_NAME, t1.SCHOOL_NAME, MAX(t0.NUM_ENROLLED_STUDENTS) OVER (ORDER BY t0.TIP_SUBJECT_OFFERED_KEY ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING) AS max_enrolled_students, t0.OFFER_DEPT_NAME AS join_dept_name FROM TIP_SUBJECT_OFFERED t0 JOIN STUDENT_DEPARTMENT t1 ON t0.OFFER_DEPT_CODE = t1.DEPARTMENT_CODE WHERE t0.NUM_ENROLLED_STUDENTS >= 0 AND t0.TERM_CODE IS NOT NULL AND t0.OFFER_SCHOOL_NAME IN ('Engineering', 'Science') AND t0.IS_NO_COURSE_MATERIAL = 'N' ) cs ON ic.department_name = cs.join_dept_name ORDER BY reserved_materials_per_max_enrollment DESC